# Fix: preserve markers even on full rows
# Build the output based on the pattern:
# 1. Rows with markers OUTSIDE block's horizontal span get full fill (2s with markers) AND belong to block vertically  
# 2. All other rows get checkerboard based on (row + col) % 2

# Test input
rows, cols = 20, 20
block_rows = list(range(2, 8))  # rows 2-7, inclusive
block_cols = list(range(9, 16))  # cols 9-15, inclusive
markers = [(2,6), (3,19), (4,5), (7,1), (8,19), (12,9), (17,13), (19,15)]

# Build output
fill_rows = set(block_rows)  # block rows start as fill rows
# Add rows that have markers outside block column span
for mr, mc in markers:
    if block_cols[0] <= mc <= block_cols[-1]:
        # marker is inside block columns - this row does NOT fill
        pass
    else:
        # marker is outside block columns - add to fill rows
        fill_rows.add(mr)

print('Fill rows:', sorted(fill_rows))

output = [[0]*cols for _ in range(rows)]

for row in range(rows):
    for col in range(cols):
        # First set the pattern (checkerboard or full)
        if row in fill_rows:
            # Full fill - entire row is 2 (markers preserved below)
            output[row][col] = 2
        else:
            # Checkerboard
            if (row + col) % 2 == 0:
                output[row][col] = 2
            else:
                output[row][col] = 0

        # Preserve markers
        if (row, col) in markers:
            output[row][col] = 1

print('Final JSON:', {
    "action": "submit", 
    "grid": output
})
